	/* Cogit>>#printPCMapPairsFor: */
#if VMInvestigations
void
printPCMapPairsFor(CogMethod *cogMethod)
{
    unsigned char annotation;
    sqInt map;
    unsigned char mapByte;
    usqInt mcpc;
    sqInt stackCheckPC;
    const char *type;
    usqInt value;

	mapByte = 0;
	mcpc = /* firstMappedPCFor: */
			((((cogMethod->cmType)) >= CMMethod)
		 && ((cogMethod->cpicHasMNUCaseOrCMIsFullBlock))
				? (((usqInt)cogMethod)) + cbNoSwitchEntryOffset
				: (((usqInt)cogMethod)) + cmNoCheckEntryOffset);
	map = ((((usqInt)cogMethod)) + ((cogMethod->blockSize))) - 1;
	stackCheckPC = (((sqInt)cogMethod)) + ((cogMethod->stackCheckOffset));
	while (((mapByte = byteAt((void *)(map)))) != MapEnd) {
		annotation = ((usqInt)(mapByte)) >> AnnotationShift;
		if (annotation == IsAnnotationExtension) {
			value = (mapByte & DisplacementMask) + IsSendCall;
		}
		else {
			value = annotation;
			mcpc += 1 /* codeGranularity */ * ((annotation
		? mapByte & DisplacementMask
		: ((sqInt)((usqInt)((mapByte - DisplacementX2N)) << AnnotationShift))));
		}
		if (((value >= IsDirectedSuperSend) && (value <= IsDirectedSuperBindingSend))) {
			if (value == IsDirectedSuperSend) {
				type = "DirectedSuperSend";
			}
			else {
				type = "DirectedSuperBindingSend";
			}
		}
		else {
			switch (value) {
			case IsDisplacementX2N:
				type = "DisplacementX2N";
				break;
			case IsAnnotationExtension:
				type = "AnnotationExtension";
				break;
			case IsObjectReference:
				type = "ObjectReference";
				break;
			case IsAbsPCReference:
				type = "AbsPCReference";
				break;
			case HasBytecodePC:
				if (mcpc == stackCheckPC) {
					type = "StackCheck/BCPC";
				}
				else {
					type = "HasBytecodePC";
				}
				break;
			case IsRelativeCall:
				type = "RelativeCall";
				break;
			case IsSendCall:
				type = "SendCall";
				break;
			case IsSuperSend:
				type = "SuperSend";
				break;
			default:
				type = null;
			}
		}
		if (type) {
			fprintf(getTranscript(),
					"%" PRIxSQINT ": %02x %ld (%s) 0x%x @ %p\n",
					map,
					mapByte,
					annotation,
					type,
					((int) (mapByte & DisplacementMask)),
					((void *)mcpc));
		}
		else {
			fprintf(getTranscript(),
					"%" PRIxSQINT ": %02x %ld (??? %d) 0x%x @ %p\n",
					map,
					mapByte,
					annotation,
					((int) value),
					((int) (mapByte & DisplacementMask)),
					((void *)mcpc));
		}
		map -= 1;
	}
}
#endif /* VMInvestigations */


