/*	Unlink all sends in cog methods. Free all PICs with the selector, or
	Closed PICs with an
	MNU case if isMNUSelector. First check if any method actually has the
	selector; if not
	there can't be any linked send to it. This routine (including descendents)
	is performance
	critical. It contributes perhaps 30% of entire execution time in Compiler
	recompileAll.  */

	/* Cogit>>#unlinkSendsOf:isMNUSelector: */
void
unlinkSendsOfisMNUSelector(sqInt selector, sqInt isMNUSelector)
{
    sqInt annotation;
    CogMethod *cogMethod;
    sqInt map;
    sqInt mapByte;
    usqInt mcpc;
    sqInt mustScanAndUnlink;
    sqInt result;

	if (!methodZoneBase) {
		return;
	}
	cogMethod = ((CogMethod *) methodZoneBase);
	mustScanAndUnlink = 0;
	if (isMNUSelector) {
		while (cogMethod < (limitZony())) {
			if (!(((cogMethod->cmType)) == CMFree)) {
				if (/* cpicHasMNUCase */
					((cogMethod->cpicHasMNUCaseOrCMIsFullBlock))
				 && (((cogMethod->cmType)) == CMClosedPIC)) {
					assert(isCMClosedPIC(((CogBlockMethod *) cogMethod)));
					freeMethod(cogMethod);
					mustScanAndUnlink = 1;
				}
				else {
					if (((cogMethod->selector)) == selector) {
						mustScanAndUnlink = 1;
						if (/* isCMAnyPIC */
							(((cogMethod->cmType)) <= CMOpenPIC)
						 && (((cogMethod->cmType)) >= CMClosedPIC)) {
							freeMethod(cogMethod);
						}
					}
				}
			}
			cogMethod = ((CogMethod *) (roundUpToMethodAlignment(backEnd, (((usqInt)cogMethod)) + ((cogMethod->blockSize)))));
		}
	}
	else {
		while (cogMethod < (limitZony())) {
			if ((!(((cogMethod->cmType)) == CMFree))
			 && (((cogMethod->selector)) == selector)) {
				mustScanAndUnlink = 1;
				if (/* isCMAnyPIC */
					(((cogMethod->cmType)) <= CMOpenPIC)
				 && (((cogMethod->cmType)) >= CMClosedPIC)) {
					freeMethod(cogMethod);
				}
			}
			cogMethod = ((CogMethod *) (roundUpToMethodAlignment(backEnd, (((usqInt)cogMethod)) + ((cogMethod->blockSize)))));
		}
	}
	if (!mustScanAndUnlink) {
		return;
	}
	codeModified = 0;
	voidOpenPICList();
	cogMethod = ((CogMethod *) methodZoneBase);
	while (cogMethod < (limitZony())) {
		if (((cogMethod->cmType)) >= CMMethod) {
			/* begin mapFor:performUntil:arg: */
			mapByte = 0;
			mcpc = /* firstMappedPCFor: */
					((((cogMethod->cmType)) >= CMMethod)
				 && ((cogMethod->cpicHasMNUCaseOrCMIsFullBlock))
						? (((usqInt)cogMethod)) + cbNoSwitchEntryOffset
						: (((usqInt)cogMethod)) + cmNoCheckEntryOffset);
			map = ((((usqInt)cogMethod)) + ((cogMethod->blockSize))) - 1;
			enumeratingCogMethod = cogMethod;
			while (((mapByte = byteAt((void *)(map)))) != MapEnd) {
				if (mapByte >= FirstAnnotation) {
					mcpc += (mapByte & DisplacementMask);

					/* If this is an IsSendCall annotation, peek ahead for an IsAnnotationExtension, and consume it. */
					if ((((annotation = ((usqInt)(mapByte)) >> AnnotationShift)) == IsSendCall)
					 && ((((usqInt)(((mapByte = byteAt((void *)(map - 1)))))) >> AnnotationShift) == IsAnnotationExtension)) {
						annotation += mapByte & DisplacementMask;
						map -= 1;
					}
					result = unlinkIfFreeOrLinkedSendpcof(annotation, ((char *) mcpc), ((CogMethod *) selector));
					if (result) {
						goto l1;
					}
				}
				else {
					if (mapByte < ((((usqInt)(IsAnnotationExtension) << AnnotationShift)))) {
						mcpc += ((((usqInt)((mapByte - DisplacementX2N)) << AnnotationShift)));
					}
				}
				map -= 1;
			}
			/* end mapFor:performUntil:arg: */
l1:;
		}
		else {
			if (((cogMethod->cmType)) == CMOpenPIC) {
				/* begin setCodeModified */
				codeModified = 1;
				addToOpenPICList(cogMethod);
			}
		}
		cogMethod = ((CogMethod *) (roundUpToMethodAlignment(backEnd, (((usqInt)cogMethod)) + ((cogMethod->blockSize)))));
	}
	if (codeModified) {
		flushICacheFromto(backEnd, ((usqInt)methodZoneBase), freeStart());
	}

	/* After possibly updating inline caches we need to flush the icache.
	   And ensure code zone is executable.  May merely have freed methods... */

	/* begin ensureExecutableCodeZone */
}


