	/* #MoveR:Aw: #gen:operand:literal: #checkLiteral:forInstruction: */
	genoperandoperand(MoveRAw, scratch1, freeStartAddress());

	/* begin genStoreHeader:intoNewInstance:using: */
	/* MoveCq:R: */
	/* gen:quickConstant:operand: */
	/* checkQuickConstant:forInstruction: */
	genoperandoperand(MoveCqR, newFloatHeader, scratch1);

	/* #MoveR:Mw:r: #gen:operand:quickConstant:operand: #checkQuickConstant:forInstruction: */
	genoperandoperandoperand(MoveRMwr, scratch1, 0, resultReg);

