	/* begin genMarshallNArgs:arg:arg:arg:arg: */
	/* SubCq:R: */
	/* gen:quickConstant:operand: */
	/* checkQuickConstant:forInstruction: */
	genoperandoperand(SubCqR, 32, RSP);

