static sqInt
genCallPrimitiveBytecode(void)
{
    usqInt prim;
    usqInt primSet;

	if (byte2 < 128) {
		return (bytecodePC == initialPC
				? 0
				: EncounteredUnknownBytecode);
	}
	prim = ((((usqInt)((byte2 - 128)) << 8))) + byte1;
	primSet = ((prim) >> 13) & 3;
	prim = prim & 0x1FFF;
	if (primSet == 1) {
		return genLowcodeInlinePrimitive(prim);
	}
	return EncounteredUnknownBytecode;
}


