    sqInt argNeedsReg;
    sqInt argReg;
    sqInt argRegSqInt;
    BytecodeDescriptor *branchDescriptor;
    BytecodeDescriptor *branchDescriptor1;
    sqInt i;
    void *jumpTarget;
    sqInt nExts;
    sqInt nextPC;
    sqInt nextPCSqInt;
    sqInt postBranchPC;
    sqInt postBranchPCSqInt;
    BytecodeDescriptor *primDescriptor;
    sqInt rcvrIsConstant;
    sqInt rcvrNeedsReg;
    sqInt rcvrReg;
    sqInt rcvrRegSqInt;
